import itertools
G = ((0,0,1),(1,1,2),(1,1,2)); INV=(2,1,0)
KINDS = [
    (('c',0), ('c',2)), (('c',0), ('v',0)), (('c',0), ('v',1)),
    (('v',0), ('c',2)), (('v',1), ('c',2)), (('v',0), ('v',0)),
    (('v',1), ('v',1)), (('v',0), ('v',1)), (('v',1), ('v',0)),
]
def val(spec, x):
    if spec[0]=='c': return spec[1]
    return INV[x] if spec[1] else x
def required(kind, x):
    L,R = kind
    return G[val(L,x)][val(R,x)]
best=[]
for n1 in (1,2,3):
    for c1 in itertools.combinations(range(9), n1):
        for n2 in (1,2,3):
            for c2 in itertools.combinations(range(9), n2):
                sat=False
                for x1 in range(3):
                    for x2 in range(3):
                        ok1 = any(required(KINDS[k], x2)==x1 for k in c1)
                        ok2 = any(required(KINDS[k], x1)==x2 for k in c2)
                        if ok1 and ok2: sat=True; break
                    if sat: break
                if not sat:
                    best.append((c1,c2))
print('unsatisfiable 2-link configs:', len(best))
for c1,c2 in best[:10]:
    print(' e1:', [KINDS[k] for k in c1], ' e2:', [KINDS[k] for k in c2])
PYEOF
